--
-- Dumping data for table `persona_knowledge_chunks`
--

INSERT INTO `persona_knowledge_chunks` (`id`, `persona_id`, `sumber`, `judul`, `teks_chunk`, `referensi`, `embedding`, `is_aktif`, `created_at`, `updated_at`) VALUES
(1, 1, 'profil', 'Latar belakang dr. Gamal Albinsaid', 'dr. Gamal Albinsaid lahir di Kota Malang, 8 September 1989. Ia menempuh pendidikan dasar hingga menengah di Malang, lalu kuliah S1 dan S2 di Fakultas Kedokteran Universitas Brawijaya. Ia dikenal sebagai penggagas Klinik Asuransi Sampah, sebuah model layanan kesehatan yang preminya dibayar dengan sampah. Pada Pemilu 2024 ia terpilih sebagai Anggota DPR RI dari Dapil Jawa Timur V (PKS) dengan 110.385 suara dan ditempatkan di Komisi X.', 'Profil publik / pemberitaan media (perlu verifikasi tim sebelum publikasi)', NULL, 1, '2026-09-06 06:03:47', '2026-09-06 06:03:47'),
(2, 1, 'isu', 'Fokus di Komisi X', 'Sebagai anggota Komisi X, dr. Gamal Albinsaid menaruh perhatian besar pada kualitas dan kesejahteraan guru, pemerataan akses pendidikan hingga daerah terpencil, serta isu gizi dan kesehatan anak sekolah. Ia juga menyoroti pentingnya perlindungan data pribadi warga.', 'Rangkuman posisi publik (perlu verifikasi tim)', NULL, 1, '2026-09-06 06:03:47', '2026-09-06 06:03:47'),
(3, 2, 'profil', 'Latar belakang Ahmad Basarah', 'Ahmad Basarah adalah politikus PDI Perjuangan kelahiran Jakarta yang berkarier panjang di Malang sebagai dosen Fakultas Hukum Universitas Islam Malang. Ia meraih gelar doktor ilmu hukum dari Universitas Diponegoro. Ia menjabat Wakil Ketua MPR RI periode 2018–2024, dan pada periode 2024–2029 menjadi Ketua Fraksi PDIP di MPR RI serta Anggota Komisi XIII DPR RI dari Dapil Jawa Timur V dengan 89.769 suara.', 'Profil publik / pemberitaan media (perlu verifikasi tim sebelum publikasi)', NULL, 1, '2026-09-06 06:03:47', '2026-09-06 06:03:47'),
(4, 2, 'isu', 'Isu utama Ahmad Basarah', 'Ahmad Basarah konsisten mengangkat penguatan ideologi Pancasila melalui Badan Pembinaan Ideologi Pancasila (BPIP), isu-isu ketatanegaraan dan konstitusi, serta menyampaikan sikap resmi DPP PDI Perjuangan sebagai juru bicara partai.', 'Rangkuman posisi publik (perlu verifikasi tim)', NULL, 1, '2026-09-06 06:03:47', '2026-09-06 06:03:47');

