INSERT INTO `pesan` (`id`, `percakapan_id`, `pengirim`, `isi_pesan`, `meta`, `created_at`) VALUES
(1, 1, 'warga', 'Apa program Anda di dalam bidang Pendidikan?', NULL, '2026-09-08 08:23:08'),
(2, 1, 'ai', '[MODE DEMO — belum terhubung ke Claude API]\n\nBerdasarkan data publik yang tersedia, terima kasih atas pertanyaan/aspirasi Anda: \"Apa program Anda di dalam bidang Pendidikan?\".\n\nPada versi produksi, jawaban ini akan dihasilkan AI berdasarkan knowledge base persona. Aspirasi Anda tetap tercatat untuk ditindaklanjuti.', '{\"usage\": [], \"chunks\": [{\"id\": 2, \"judul\": \"Fokus di Komisi X\", \"score\": 0.0882, \"sumber\": \"isu\"}, {\"id\": 1, \"judul\": \"Latar belakang dr. Gamal Albinsaid\", \"score\": 0.0677, \"sumber\": \"profil\"}]}', '2026-09-08 08:23:08'),
(10, 5, 'ai', 'Assalamualaikum warahmatullahi wabarakatuh, salam sejahtera untuk kita semua. 🙏\n\nSaya **Ahmad Basarah**, Anggota DPR RI Fraksi PDI Perjuangan dari Dapil Jawa Timur 5 (Malang Raya), bertugas di Komisi XIII. Saya berkarier panjang di Malang sebagai dosen Fakultas Hukum Universitas Islam Malang, meraih gelar doktor ilmu hukum dari Universitas Diponegoro, dan pernah menjabat Wakil Ketua MPR RI periode 2018–2024.\n\nSilakan sampaikan pertanyaan atau aspirasi Anda — terutama seputar ketatanegaraan, konstitusi, ideologi Pancasila, atau sikap resmi partai. Setiap aspirasi akan dicatat untuk ditindaklanjuti.', '{\"scripted\": true}', '2026-09-10 14:16:08'),
(11, 6, 'ai', 'Halo, warga… Assalamualaikum, salam hormat! 🙏\n\nSaya **dr. Gamal Albinsaid**, lahir di Kota Malang pada 8 September 1989. Pendidikan dasar hingga menengah saya tempuh di Malang (MI Jenderal Sudirman, SMP Negeri 3 Malang, SMA Negeri 3 Malang), lalu S1 dan S2 di Fakultas Kedokteran Universitas Brawijaya. Saat ini saya Anggota DPR RI Fraksi PKS dari Dapil Jawa Timur 5 (Malang Raya), bertugas di Komisi X yang membidangi pendidikan, kebudayaan, ristek, pariwisata, ekonomi kreatif, kepemudaan, olahraga, dan perpustakaan.\n\nSemoga Anda dan keluarga di rumah selalu sehat — itu yang paling penting.\n\nApa yang bisa saya bantu sebagai wakil Anda di DPR RI? Silakan sampaikan pertanyaan atau aspirasi Anda.', '{\"scripted\":true}', '2026-09-15 09:54:47'),
(12, 6, 'warga', 'Berapa anggaran MBG tahun Anggaran 2026?', NULL, '2026-09-15 09:56:25'),
(13, 6, 'ai', '[MODE DEMO — belum terhubung ke Claude API]\n\nBerdasarkan data publik yang tersedia, terima kasih atas pertanyaan/aspirasi Anda: \"Berapa anggaran MBG tahun Anggaran 2026?\".\n\nPada versi produksi, jawaban ini akan dihasilkan AI berdasarkan knowledge base persona. Aspirasi Anda tetap tercatat untuk ditindaklanjuti.', '{\"chunks\":[{\"id\":1,\"judul\":\"Latar belakang dr. Gamal Albinsaid\",\"sumber\":\"profil\",\"score\":0},{\"id\":2,\"judul\":\"Fokus di Komisi X\",\"sumber\":\"isu\",\"score\":0}],\"usage\":[]}', '2026-09-15 09:56:25');

